import React, { createContext, useState } from "react";

export const OrderContext = createContext();

const OrderProvider = ({ children }) => {
  const [isOrderFormValid, setIsOrderFormValid] = useState(false);
  const [isOrderInvoiceFormValid, setIsOrderInvoiceFormValid] = useState(false);

  const [orderData, setOrderData] = useState({
    email: "",

    deliveryMethod: {
      method: "",
      pickupPoint: null
    },

    shippingAddress: {
      costumerName: "",
      costumerSurname: "",
      address: "",
      company: "",
      postalCode: "",
      city: "",
      phoneNumber: "",
      phonePrefix: "",
      selectedCount: "",
      totalCost: "",
      shipping: "",
      productImage: "",
      productName: "",
      productPrice: "",
      discountApplied: false,
      discountValue: 0,
      wantInvoice: false
    },

    billingAddress: {
      costumerName: "",
      costumerSurname: "",
      address: "",
      company: "",
      postalCode: "",
      city: "",
      phoneNumber: "",
      nip: "",
      phonePrefix: "",
      selectedCount: "",
      totalCost: "",
      shipping: "",
      productImage: "",
      productName: "",
      productPrice: ""
    },

    useDifferentBilling: false,

    acceptedAge: false,
    acceptedRodo: false,
  });


  const [showAgeAlert, setShowAgeAlert] = useState(false);
  const [showRodoAlert, setShowRodoAlert] = useState(false);


 const updateOrderData = (key, value) => {
  console.log("CONTEXT UPDATE:", key, value);

  setOrderData((prev) => {
    const newData = {
      ...prev,
      [key]: value,
    };

    console.log("NEW ORDER DATA:", newData);

    return newData;
  });
};


  const updateNestedOrderData = (section, key, value) => {
    setOrderData(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [key]: value,
      }
    }));
  };


  return (
    <OrderContext.Provider 
      value={{
        orderData,
        updateOrderData,
        updateNestedOrderData,

        isOrderFormValid,
        setIsOrderFormValid,

        isOrderInvoiceFormValid,
        setIsOrderInvoiceFormValid,

        setOrderData,

        showRodoAlert,
        setShowRodoAlert,

        showAgeAlert,
        setShowAgeAlert
      }}
    >
      {children}
    </OrderContext.Provider>
  );
};

export default OrderProvider;